const AU_warn=(x,y,s,col=ORG)=>`<path d="M${x},${y-s*.55} L${x+s*.6},${y+s*.45} L${x-s*.6},${y+s*.45} Z" fill="${YEL}" stroke="${col}" stroke-width="4" stroke-linejoin="round"/>`+AU_T(x,y+s*.32,'!',{fs:Math.round(s*.6),fw:800,a:'middle',fill:INK});
